using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Uri baseAddress;
    private Task<CapturedRequest>? captured;

    private sealed record CapturedRequest(string Method, string Path, string? ContentType, string Body);

    public HttpPaymentGatewayTests()
    {
        // Retry on the rare chance the random port is taken.
        for (var attempt = 0; ; attempt++)
        {
            var port = Random.Shared.Next(20000, 60000);
            var prefix = $"http://127.0.0.1:{port}/";
            try
            {
                listener.Prefixes.Add(prefix);
                listener.Start();
                baseAddress = new Uri(prefix);
                break;
            }
            catch (HttpListenerException) when (attempt < 10)
            {
                listener.Prefixes.Clear();
            }
        }

        client = new HttpClient { BaseAddress = baseAddress };
    }

    private void Provider(int status, string? body)
    {
        captured = Task.Run(async () =>
        {
            var context = await listener.GetContextAsync();
            using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            var request = new CapturedRequest(
                context.Request.HttpMethod,
                context.Request.Url!.AbsolutePath,
                context.Request.ContentType,
                await reader.ReadToEndAsync());

            context.Response.StatusCode = status;
            if (body is not null)
            {
                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.ContentType = "application/json";
                await context.Response.OutputStream.WriteAsync(bytes);
            }
            context.Response.Close();
            return request;
        });
    }

    private Task<AuthorizationOutcome> Authorize(decimal amount = 12.50m, string currency = "eur") =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task It_posts_the_reference_amount_and_currency_as_json_to_the_authorizations_endpoint()
    {
        Provider(200, """{"status":"approved"}""");

        await Authorize(12.50m, "eur");

        var request = await captured!;
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Provider(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Provider(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Provider(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_approving_looking_body()
    {
        Provider(402, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_without_a_body_is_a_decline()
    {
        Provider(402, null);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("{}")]
    [InlineData("null")]
    public async Task An_answer_that_does_not_say_approved_is_never_treated_as_approved(string body)
    {
        Provider(200, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.UnprocessableEntity)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_error_statuses_surface_as_errors_not_as_declines(HttpStatusCode status)
    {
        Provider((int)status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal(status, error.StatusCode);
    }

    [Theory]
    [InlineData("not json")]
    [InlineData("")]
    [InlineData("[]")]
    public async Task A_success_answer_that_is_not_the_expected_json_object_surfaces_as_an_error(string body)
    {
        Provider(200, body);

        await Assert.ThrowsAnyAsync<Exception>(Authorize);
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
EOF
